<?php $filter=['q'=>trim((string)($_GET['q']??'')),'categoria'=>(string)($_GET['categoria']??''),'periodo'=>(string)($_GET['periodo']??''),'status'=>(string)($_GET['status']??''),'ordem'=>(string)($_GET['ordem']??'ano_asc')];$pg=max(1,(int)($_GET['p']??1));$found=get_markers($filter,$pg,12); ?>
<header class="page-heading page-heading-slim"><div class="section-overline">O ARQUIVO VIVO <span class="overline-sep">/</span> 04</div><h1>O acervo de <em>marcos.</em></h1><p>Localize, examine e compare acontecimentos. O estatuto documental de cada registro aparece no próprio dossiê.</p></header>
<form class="archive-filter" method="get" action="index.php"><input type="hidden" name="page" value="acervo">
 <label class="search-wrap"><span>⌕</span><input name="q" value="<?=h($filter['q'])?>" placeholder="Pesquisar no acervo..." aria-label="Pesquisar"></label>
 <select name="categoria" aria-label="Área"><option value="">Todas as áreas</option><?php foreach(get_categories() as $c):?><option value="<?=h($c)?>" <?=$filter['categoria']===$c?'selected':''?>><?=h($c)?></option><?php endforeach;?></select>
 <select name="periodo" aria-label="Período"><option value="">Todos os períodos</option><?php foreach(get_periods() as $c):?><option value="<?=h($c)?>" <?=$filter['periodo']===$c?'selected':''?>><?=h($c)?></option><?php endforeach;?></select>
 <select name="ordem" aria-label="Ordem"><option value="ano_asc" <?=$filter['ordem']==='ano_asc'?'selected':''?>>Mais antigos</option><option value="ano_desc" <?=$filter['ordem']==='ano_desc'?'selected':''?>>Mais recentes</option></select><select name="status" aria-label="Situação"><option value="">Todas as situações</option><?php foreach(['aprovado','pendente','importado','demonstracao','rejeitado'] as $c):?><option value="<?=$c?>" <?=$filter['status']===$c?'selected':''?>><?=status_text($c)?></option><?php endforeach;?></select>
 <button class="btn btn-dark btn-filter" type="submit">Buscar ↗</button>
</form>
<div class="archive-subhead"><span><?=short_num($found['total'])?> RESULTADOS <i>•</i> PÁGINA <?=$found['page']?> / <?=$found['pages']?></span><div><?php if(is_admin()):?><a href="<?=mat_url('editar')?>">＋ NOVO DOSSIÊ</a><?php endif;?><a href="export.php?format=csv">⇩ CSV</a><a href="export.php?format=json">⇩ JSON</a><a href="export.php?format=sql">⇩ SQL</a></div></div>
<div class="archive-list">
<?php foreach($found['rows'] as $m):?><a href="<?=mat_url('marco',['id'=>$m['id']])?>" class="archive-item"><span class="archive-year"><?=yfmt((int)$m['ano'])?></span><div class="archive-core"><span class="arch-category"><span class="category-dot <?=cat_tone((string)$m['categoria'])?>"></span><?=h($m['categoria'])?></span><h2><?=h($m['titulo'])?></h2><p><?=h($m['descricao'])?></p></div><div class="archive-meta"><span class="status-pill <?=$m['status']==='aprovado'?'valid':''?>"><?=status_text($m['status'])?></span><span class="archive-forward">↗</span></div></a><?php endforeach;?>
<?php if(!$found['rows']):?><div class="empty-box">Nenhum registro para esses filtros. <a href="<?=mat_url('acervo')?>">Limpar pesquisa ↗</a></div><?php endif;?></div>
<div class="pagination"><span><?=short_num($found['total'])?> registros</span><div><?php if($pg>1):?><a href="<?=mat_url('acervo',array_merge($filter,['p'=>$pg-1]))?>">← Anterior</a><?php endif;?><?php if($pg<$found['pages']):?><a href="<?=mat_url('acervo',array_merge($filter,['p'=>$pg+1]))?>">Próxima →</a><?php endif;?></div></div>
